Subject: [PATCH] fixed a bug I introduced in
 f2dbecb84ec45427f76bf02fc29fa1a8b2c9dd2e. mCurPage should be set to null
 immediately when last page is popped, even if there is an transition
 animation to play


diff --git a/PaginizeLib/src/net/neevek/android/lib/paginize/PageManager.java b/PaginizeLib/src/net/neevek/android/lib/paginize/PageManager.java
index c046b7a..51ee781 100644
--- a/PaginizeLib/src/net/neevek/android/lib/paginize/PageManager.java
+++ b/PaginizeLib/src/net/neevek/android/lib/paginize/PageManager.java
@@ -326,6 +326,9 @@ public class PageManager {
       }
     }

+    mContainerView.removeView(removedPage.getView());
+    mCurPage = prevPage;
+
     int animationDuration = removedPage.getAnimationDuration();
     if (animationDuration == -1 && mPageAnimator != null) {
       animationDuration = mPageAnimator.getAnimationDuration();
@@ -344,10 +347,8 @@ public class PageManager {
   }

   private void doFinalWorkForPopPageInternal(Page removedPage, Page prevPage) {
-    mContainerView.removeView(removedPage.getView());
     removedPage.onDetach();
     removedPage.onHidden();
-    mCurPage = prevPage;

     if (prevPage != null) {
       prevPage.onUncovered(removedPage.getReturnData());
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the `mCurPage` not being set to null immediately when the last page was popped, which could lead to inconsistencies in the page state during transition animations. This oversight meant that the current page reference could still point to a page that was no longer visible, potentially causing unexpected behavior in the application.

        Commit message:
        fixed a bug I introduced in
 f2dbecb84ec45427f76bf02fc29fa1a8b2c9dd2e. mCurPage should be set to null
 immediately when last page is popped, even if there is an transition
 animation to play  

        Patch:

   private void popPageInternal(final Page removedPage, boolean animated, boolean hint) {
     final Page prevPage;
     if (mPageStack.size() > 0) {    // this check is always necessary
       prevPage = mPageStack.getLast();

       if (animated && mPageAnimator != null && !removedPage.onPopPageAnimation(removedPage, prevPage, hint)) {
         mPageAnimator.onPopPageAnimation(removedPage, prevPage, hint);
       }

       prevPage.getView().setVisibility(View.VISIBLE);
     } else {
       prevPage = null;

       if (animated && mPageAnimator != null && !removedPage.onPopPageAnimation(removedPage, null, hint)) {
         mPageAnimator.onPopPageAnimation(removedPage, null, hint);
       }
     }

+    mContainerView.removeView(removedPage.getView());
+    mCurPage = prevPage;
+
     int animationDuration = removedPage.getAnimationDuration();
     if (animationDuration == -1 && mPageAnimator != null) {
       animationDuration = mPageAnimator.getAnimationDuration();
     }
     if (animated && animationDuration != -1) {
       removedPage.postDelayed(new Runnable() {
         @Override
         public void run() {
           doFinalWorkForPopPageInternal(removedPage, prevPage);
         }
       }, animationDuration);

     } else {
       doFinalWorkForPopPageInternal(removedPage, prevPage);
     }
   }

   private void doFinalWorkForPopPageInternal(Page removedPage, Page prevPage) {
-    mContainerView.removeView(removedPage.getView());
     removedPage.onDetach();
     removedPage.onHidden();
-    mCurPage = prevPage;

     if (prevPage != null) {
       prevPage.onUncovered(removedPage.getReturnData());
     }
   }



